import re

from robot.api import logger

from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser

UL = re.compile(r'UL=(\d+)')
DL = re.compile(r'DL=(\d+)')


class BearerDispFailure(Exception):
    """
    Exception class for bearer_disp
    """
    pass


def parse_arp(value):
    """
    Parse ARP.

    :param value:
    :return:
    """
    return {
        'priority': re.search(r'\d+', value).group(0),
        'vulnerability': _get_vulnerability_from_arp(value),
        'preemtability': _get_preemtability_from_arp(value)
    }


def parse_mbr(value):
    """
    Parse MBR to separate UL and DL values.

    :param value:
    :return:
    """
    if value == '-':
        return {'mbr_ul': None, 'mbr_dl': None}
    else:
        return {
            'mbr_ul': re.search(r'UL=(\d+)', value).group(1),
            'mbr_dl': re.search(r'DL=(\d+)', value).group(1)
        }


def parse_gbr(value):
    """
    Parse GBR to separate UL and DL values.

    :param value:
    :return:
    """
    if value == '-':
        return {'gbr_ul': None, 'gbr_dl': None}
    else:
        return {
            'gbr_ul': re.search(r'UL=(\d+)', value).group(1),
            'gbr_dl': re.search(r'DL=(\d+)', value).group(1)
        }


def parse_qci(value):
    """
    Converts QCI values to integer.

    :param value:
    :return:
    """
    return int(value)


def parse_id_teid(value):
    """
    Parse TEID columns to return only IP address.

    :param value:
    :return:
    """
    return value.split()[0]


def _get_vulnerability_from_arp(arp):
    if 'v+' in arp:
        return 1
    elif 'v-' in arp:
        return 0
    elif 'v' in arp:
        return 1
    else:
        return 0


def _get_preemtability_from_arp(arp):
    if 'p+' in arp:
        return 1
    elif 'p-' in arp:
        return 0
    elif 'p' in arp:
        return 1
    else:
        return 0


class AtParser(object):
    def parse(self, unparsed):
        """Each line is as list of small dicts. It unpacks those small dicts into bigger one."""
        parsed = []
        for match in self._line_template.searchString(unparsed):
            d = {}
            for property in match:
                d.update(list(property.items()))
            parsed.append(d)
        return parsed


class DummyParser(AtParser):
    def parse(self, output):
        """Returns what was send to it."""
        return output


class BearerDisp(EgateCommandBase):
    """
    Parser for bearer_disp command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(BearerDisp, self).__init__()
        self.command = 'bearer_disp'
        self.params = params
        self.to_execute = self.command
        self.executed_phrase = r'.*?UE(\s|\-)\d+.*?EGATE>'
        self.fail_regexp = 'Error:|ERR:'
        self._build_command()
        self.parsers = {
            "ue": self._parse_with_ue_id_at_ue,
            "mme": self._parse_with_ue_id_at_mme,
            "pgw": self._parse_with_ue_id_at_pgw,
            "sgw": self._parse_with_ue_id_at_sgw,
            "enb": self._parse_with_ue_id_at_enb,
            "gnb": self._parse_with_ue_id_at_gnb
        }

    def execute_and_parse(self, egate_id=0):
        """
        Execute bearer_disp command.

        :param egate_id:
        :return: command status and output
        """
        status, output = self.execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            parsed_output = self._parse_based_on_input_params(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return status, parsed_output
        else:
            raise BearerDispFailure(output)

    def _build_command(self):
        """
        Build bearer_disp command.

        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_based_on_input_params(self, output):
        try:
            at = self.params['at'].split(':')[0]
            return self.parsers[at](output)
        except KeyError:
            return self._parse_with_ue_id(output)

    def _parse_with_ue_id(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower() for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('QCI', parse_qci)
        cmd_parser.parse_column_value_with_custom_function('ARP', parse_arp)
        cmd_parser.parse_column_value_with_custom_function('MBR, kbps', parse_mbr)
        cmd_parser.parse_column_value_with_custom_function('GBR, kbps', parse_gbr)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_ue(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower().replace(' ', '_') for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('QCI', parse_qci)
        cmd_parser.parse_column_value_with_custom_function('MBR, kbps', parse_mbr)
        cmd_parser.parse_column_value_with_custom_function('GBR, kbps', parse_gbr)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_mme(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower().replace('->', '_').replace(' ', '_') for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('QCI', parse_qci)
        cmd_parser.parse_column_value_with_custom_function('ARP', parse_arp)
        cmd_parser.parse_column_value_with_custom_function('MBR, kbps', parse_mbr)
        cmd_parser.parse_column_value_with_custom_function('GBR, kbps', parse_gbr)
        cmd_parser.parse_column_value_with_custom_function('IP->TEID DL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('IP->TEID UL', parse_id_teid)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_pgw(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower().replace('->', '_').replace(' ', '_') for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('QCI', parse_qci)
        cmd_parser.parse_column_value_with_custom_function('ARP', parse_arp)
        cmd_parser.parse_column_value_with_custom_function('MBR, kbps', parse_mbr)
        cmd_parser.parse_column_value_with_custom_function('GBR, kbps', parse_gbr)
        cmd_parser.parse_column_value_with_custom_function('IP->TEID DL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('IP->TEID UL', parse_id_teid)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_sgw(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower().replace('->', '_').replace(' ', '_') for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('QCI', parse_qci)
        cmd_parser.parse_column_value_with_custom_function('ARP', parse_arp)
        cmd_parser.parse_column_value_with_custom_function('MBR, kbps', parse_mbr)
        cmd_parser.parse_column_value_with_custom_function('GBR, kbps', parse_gbr)
        cmd_parser.parse_column_value_with_custom_function('S1U IP->TEID DL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('S1U IP->TEID UL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('S5U IP->TEID DL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('S5U IP->TEID UL', parse_id_teid)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_enb(self, cmd_output):
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        parsed_lines = cmd_parser.get_list_of_output_parsed_lines()
        columns_names = [column.lower().replace('->', '_').replace(' ', '_') for column in parsed_lines[0]]

        cmd_parser.parse_column_value_with_custom_function('IP->TEID DL', parse_id_teid)
        cmd_parser.parse_column_value_with_custom_function('IP->TEID UL', parse_id_teid)

        return self._create_output_from_parsed_lines(columns_names, parsed_lines)

    def _parse_with_ue_id_at_gnb(self, cmd_output):
        return cmd_output

    def _create_output_from_parsed_lines(self, columns_names, parsed_lines):
        parsed_output = []

        for line in parsed_lines[1:]:
            parsed_output_line = {}
            for idx, value in enumerate(line):
                if isinstance(value, dict):
                    parsed_output_line.update(value)
                else:
                    parsed_output_line[columns_names[idx]] = None if value == '-' else value
            parsed_output.append(parsed_output_line)
        return parsed_output
